	}, false, tuiweave.Dark())
	if editor.Dirty() {
		t.Fatalf("new editor should start clean")
	}

	editor.args.InsertString(" --temp 0.7")
	if !editor.Dirty() {
		t.Fatalf("editor should be dirty after args change")
	}
}

