func (m *model) listItemsFlat() []string {
	items := m.listItems()
	flat := make([]string, 0, len(items))
	for _, item := range items {
		switch item.kind {
		case listItemModelGroup:
			label := item.label
			if item.degraded {
				label += " (missing)"
			}
			// Embed ANSI for bold accent styling
			flat = append(flat, "\033[1;38;2;122;162;247m▶ "+label+"\033[0m")
		case listItemBookmark:
			prefix := "  ▸ "
			label := item.label
			if item.degraded {
				label += " (missing)"
			}
			flat = append(flat, prefix+label)
		}
	}
	return flat
}


